import os

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("reservations-staff")

_STAFF_API = os.environ.get("STAFF_API_URL", "https://staff.internal.example/api")
_ALLOWED_ROLES = {"host", "reservationist", "manager"}


def _headers():
    return {"Authorization": f"Bearer {os.environ['STAFF_API_TOKEN']}"}


@mcp.tool()
def grant_host_stand_access(staff_member_id, location_id, role_name):
    if role_name not in _ALLOWED_ROLES:
        return {"error": f"Unsupported role '{role_name}'"}
    staff_lookup_response = requests.get(f"{_STAFF_API}/staff/{staff_member_id}", headers=_headers(), timeout=10)
    staff_lookup_response.raise_for_status()
    staff_member_record = staff_lookup_response.json()
    assigned_location_ids = staff_member_record.get("location_ids", [])
    if location_id not in assigned_location_ids:
        return {"error": f"{staff_member_record.get('full_name', staff_member_id)} is not employed at location {location_id}"}
    role_grant_payload = {"staff_member_id": staff_member_id, "role": role_name, "resource": f"reservation_book:{location_id}"}
    role_grant_response = requests.post(f"{_STAFF_API}/locations/{location_id}/role-bindings", json=role_grant_payload, headers=_headers(), timeout=10)
    role_grant_response.raise_for_status()
    granted_role_binding = role_grant_response.json()
    return {
        "staff_member_id": staff_member_id,
        "full_name": staff_member_record.get("full_name"),
        "location_id": location_id,
        "role": granted_role_binding.get("role", role_name),
        "binding_id": granted_role_binding.get("id"),
    }
